import { useMemo, useState } from 'react';
import { JxChip, JxProgressCircle, JxBadge, JxPagination, JxEmptyState, JxButton } from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  quotaUsed: number;
  quotaMax: number;
  status: ProjectStatus;
}

const projects: Project[] = [
  { id: 'p1', name: 'Атлас', quotaUsed: 42, quotaMax: 100, status: 'active' },
  { id: 'p2', name: 'Нордвинд', quotaUsed: 95, quotaMax: 100, status: 'over' },
  { id: 'p3', name: 'Кобальт', quotaUsed: 18, quotaMax: 100, status: 'paused' },
  { id: 'p4', name: 'Гелиос', quotaUsed: 60, quotaMax: 100, status: 'active' },
  { id: 'p5', name: 'Меридиан', quotaUsed: 100, quotaMax: 100, status: 'over' },
  { id: 'p6', name: 'Пульсар', quotaUsed: 30, quotaMax: 100, status: 'active' },
  { id: 'p7', name: 'Вектор', quotaUsed: 5, quotaMax: 100, status: 'paused' },
  { id: 'p8', name: 'Заря', quotaUsed: 72, quotaMax: 100, status: 'active' },
  { id: 'p9', name: 'Орион', quotaUsed: 88, quotaMax: 100, status: 'over' },
  { id: 'p10', name: 'Стела', quotaUsed: 12, quotaMax: 100, status: 'paused' },
  { id: 'p11', name: 'Талисман', quotaUsed: 55, quotaMax: 100, status: 'active' },
];

const statusOptions: { value: ProjectStatus; label: string; badgeLabel: string; tone: 'success' | 'warning' | 'danger' }[] = [
  { value: 'active', label: 'Активен', badgeLabel: 'Активен', tone: 'success' },
  { value: 'paused', label: 'На паузе', badgeLabel: 'На паузе', tone: 'warning' },
  { value: 'over', label: 'Превышен', badgeLabel: 'Превышен', tone: 'danger' },
];

const pageSize = 5;

export default function ProjectSpendPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(
    statusOptions.map((option) => option.value),
  );
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(statusOptions.map((option) => option.value));
    setPage(1);
  };

  const filteredProjects = useMemo(
    () => projects.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / pageSize));
  const currentPage = Math.min(page, pageCount);
  const visibleProjects = filteredProjects.slice(
    (currentPage - 1) * pageSize,
    currentPage * pageSize,
  );

  const statusMeta = (status: ProjectStatus) =>
    statusOptions.find((option) => option.value === status)!;

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r)',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        padding: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {statusOptions.map((option) => (
          <JxChip
            key={option.value}
            active={activeStatuses.includes(option.value)}
            removable={activeStatuses.includes(option.value)}
            onClick={() => toggleStatus(option.value)}
            onRemove={() => toggleStatus(option.value)}
          >
            {option.label}
          </JxChip>
        ))}
      </div>

      {visibleProjects.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="Под выбранные фильтры не попал ни один проект."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            {visibleProjects.map((project) => {
              const meta = statusMeta(project.status);
              const percent = Math.round((project.quotaUsed / project.quotaMax) * 100);
              return (
                <div
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 'var(--jx-r)',
                    padding: '12px 4px',
                    borderBottom: '1px solid var(--jx-rule)',
                  }}
                >
                  <JxProgressCircle value={percent} showValue />
                  <span style={{ flex: 1, fontWeight: 500 }}>{project.name}</span>
                  <JxBadge tone={meta.tone}>{meta.badgeLabel}</JxBadge>
                </div>
              );
            })}
          </div>

          {pageCount > 1 && (
            <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
          )}
        </>
      )}
    </div>
  );
}

